import { type ErrorMap, unprocessable } from './errors.ts'

export const BLANK = "can't be blank"
export const INVALID = 'is invalid'

/** NIST 800-63B 5.1.1.2: at least 8 characters, and at least 64 must be accepted. */
export const PASSWORD_MIN_LENGTH = 8
export const passwordTooShort = `is too short (minimum is ${PASSWORD_MIN_LENGTH} characters)`

type Json = Record<string, unknown>

const isObject = (value: unknown): value is Json =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

/**
 * Accumulates field errors so a request reports every problem at once,
 * then throws a single 422 via `throwIfInvalid`.
 */
export class Validator {
  private readonly errors: ErrorMap = {}

  add(field: string, message: string): void {
    ;(this.errors[field] ??= []).push(message)
  }

  get valid(): boolean {
    return Object.keys(this.errors).length === 0
  }

  throwIfInvalid(): void {
    if (!this.valid) throw unprocessable(this.errors)
  }

  /** A value that must be present and a non-blank string. */
  requiredString(source: Json, field: string): string | undefined {
    const value = source[field]
    if (typeof value !== 'string' || value.trim() === '') {
      this.add(field, BLANK)
      return undefined
    }
    return value
  }

  /**
   * A patch field: absent means "leave unchanged", but when supplied it must
   * still be a non-blank string. Returns `undefined` when absent or invalid.
   */
  optionalRequiredString(source: Json, field: string): string | undefined {
    if (!(field in source)) return undefined
    return this.requiredString(source, field)
  }

  /**
   * A nullable patch field (bio, image). Absent means "leave unchanged";
   * `null` and `""` both normalize to `null`.
   */
  nullableString(source: Json, field: string): string | null | undefined {
    if (!(field in source)) return undefined
    const value = source[field]
    if (value === null || value === '') return null
    if (typeof value !== 'string') {
      this.add(field, INVALID)
      return undefined
    }
    return value
  }

  /** A password that must satisfy the length policy. `optional` skips absent keys. */
  password(source: Json, field: string, optional: boolean): string | undefined {
    if (optional && !(field in source)) return undefined
    const value = source[field]
    if (typeof value !== 'string' || value === '') {
      this.add(field, BLANK)
      return undefined
    }
    if (value.length < PASSWORD_MIN_LENGTH) {
      this.add(field, passwordTooShort)
      return undefined
    }
    return value
  }

  /** A list of tag names. Absent means "leave unchanged"; `null` is rejected. */
  tagList(source: Json, field: string): string[] | undefined {
    if (!(field in source)) return undefined
    const value = source[field]
    if (!Array.isArray(value) || value.some((tag) => typeof tag !== 'string' || tag.trim() === '')) {
      this.add(field, INVALID)
      return undefined
    }
    return [...new Set((value as string[]).map((tag) => tag.trim()))]
  }
}

/**
 * Unwraps the single root key every RealWorld payload is nested under
 * (`{"user": {...}}`, `{"article": {...}}`, ...).
 */
export function requireRoot(body: unknown, root: string): Json {
  if (!isObject(body) || !isObject(body[root])) {
    throw unprocessable({ [root]: ['is invalid'] })
  }
  return body[root]
}

