import jwt from 'jsonwebtoken'
import type { FastifyRequest } from 'fastify'
import { config } from './config.ts'
import { invalidToken, missingToken } from './errors.ts'

export interface TokenPayload {
  id: number
  username: string
}

export function signToken(payload: TokenPayload): string {
  return jwt.sign(payload, config.jwtSecret, {
    expiresIn: config.jwtExpiresIn as jwt.SignOptions['expiresIn'],
  })
}

/** Accepts both the RealWorld `Token <jwt>` scheme and standard `Bearer <jwt>`. */
export function parseAuthorizationHeader(header: string | undefined): string | null {
  if (!header) return null
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim())
  return match?.[1]?.trim() || null
}

export function verifyToken(token: string): TokenPayload {
  let decoded: unknown
  try {
    decoded = jwt.verify(token, config.jwtSecret)
  } catch {
    throw invalidToken()
  }

  if (
    typeof decoded !== 'object' ||
    decoded === null ||
    typeof (decoded as TokenPayload).id !== 'number'
  ) {
    throw invalidToken()
  }
  return decoded as TokenPayload
}

/** The authenticated user id, or `null` on endpoints where auth is optional. */
export function optionalUserId(request: FastifyRequest): number | null {
  return request.currentUserId
}

/** The authenticated user id; throws 401 when the request carried no token. */
export function requireUserId(request: FastifyRequest): number {
  if (request.currentUserId === null) throw missingToken()
  return request.currentUserId
}

