import type { FastifyInstance } from 'fastify'
import { prisma } from '../db.ts'
import { requireUserId, signToken } from '../auth.ts'
import { conflict, invalidCredentials } from '../errors.ts'
import { hashPassword, verifyPassword } from '../password.ts'
import { presentUser } from '../presenters.ts'
import { Validator, requireRoot } from '../validation.ts'

const TAKEN = 'has already been taken'

const userSelect = {
  id: true,
  email: true,
  username: true,
  bio: true,
  image: true,
  passwordHash: true,
} as const

/** Rejects a username/email already used by somebody other than `excludeId`. */
async function assertAvailable(
  fields: { username?: string | undefined; email?: string | undefined },
  excludeId?: number,
): Promise<void> {
  const clashes = await prisma.user.findMany({
    where: {
      OR: [
        ...(fields.username ? [{ username: fields.username }] : []),
        ...(fields.email ? [{ email: fields.email }] : []),
      ],
      ...(excludeId === undefined ? {} : { NOT: { id: excludeId } }),
    },
    select: { username: true, email: true },
  })
  if (clashes.length === 0) return

  const errors: Record<string, string[]> = {}
  if (fields.username && clashes.some((user) => user.username === fields.username)) {
    errors['username'] = [TAKEN]
  }
  if (fields.email && clashes.some((user) => user.email === fields.email)) {
    errors['email'] = [TAKEN]
  }
  if (Object.keys(errors).length > 0) throw conflict(errors)
}

export async function registerUserRoutes(app: FastifyInstance): Promise<void> {
  // Registration
  app.post('/users', async (request, reply) => {
    const payload = requireRoot(request.body, 'user')
    const validator = new Validator()
    const username = validator.requiredString(payload, 'username')
    const email = validator.requiredString(payload, 'email')
    const password = validator.password(payload, 'password', false)
    validator.throwIfInvalid()

    await assertAvailable({ username, email })

    const user = await prisma.user.create({
      data: {
        username: username!,
        email: email!,
        passwordHash: await hashPassword(password!),
      },
      select: userSelect,
    })

    return reply
      .status(201)
      .send({ user: presentUser(user, signToken({ id: user.id, username: user.username })) })
  })

  // Authentication
  app.post('/users/login', async (request) => {
    const payload = requireRoot(request.body, 'user')
    const validator = new Validator()
    const email = validator.requiredString(payload, 'email')
    // Login only checks that a password was supplied; policy applies on write.
    const password = payload['password']
    if (typeof password !== 'string' || password === '') validator.add('password', "can't be blank")
    validator.throwIfInvalid()

    const user = await prisma.user.findUnique({ where: { email: email! }, select: userSelect })
    if (!user || !(await verifyPassword(password as string, user.passwordHash))) {
      throw invalidCredentials()
    }

    return { user: presentUser(user, signToken({ id: user.id, username: user.username })) }
  })

  // Current user
  app.get('/user', async (request) => {
    const userId = requireUserId(request)
    const user = await prisma.user.findUniqueOrThrow({ where: { id: userId }, select: userSelect })
    return { user: presentUser(user, signToken({ id: user.id, username: user.username })) }
  })

  // Update current user
  app.put('/user', async (request) => {
    const userId = requireUserId(request)
    const payload = requireRoot(request.body, 'user')

    const validator = new Validator()
    const username = validator.optionalRequiredString(payload, 'username')
    const email = validator.optionalRequiredString(payload, 'email')
    const password = validator.password(payload, 'password', true)
    const bio = validator.nullableString(payload, 'bio')
    const image = validator.nullableString(payload, 'image')
    validator.throwIfInvalid()

    await assertAvailable({ username, email }, userId)

    const user = await prisma.user.update({
      where: { id: userId },
      data: {
        ...(username === undefined ? {} : { username }),
        ...(email === undefined ? {} : { email }),
        ...(bio === undefined ? {} : { bio }),
        ...(image === undefined ? {} : { image }),
        ...(password === undefined ? {} : { passwordHash: await hashPassword(password) }),
      },
      select: userSelect,
    })

    return { user: presentUser(user, signToken({ id: user.id, username: user.username })) }
  })
}

