import type { FastifyInstance } from 'fastify'
import { prisma } from '../db.ts'
import { optionalUserId, requireUserId } from '../auth.ts'
import { profileNotFound } from '../errors.ts'
import { presentProfile } from '../presenters.ts'

/** Filtering `followers` by the viewer turns the relation into a `following` flag. */
const profileSelect = (viewerId: number | null) =>
  ({
    id: true,
    username: true,
    bio: true,
    image: true,
    followers: { where: { followerId: viewerId ?? -1 }, select: { followerId: true } },
  }) as const

async function loadProfile(username: string, viewerId: number | null) {
  const user = await prisma.user.findUnique({
    where: { username },
    select: profileSelect(viewerId),
  })
  if (!user) throw profileNotFound()
  return user
}

interface UsernameParams {
  username: string
}

export async function registerProfileRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: UsernameParams }>('/profiles/:username', async (request) => {
    const profile = await loadProfile(request.params.username, optionalUserId(request))
    return { profile: presentProfile(profile) }
  })

  app.post<{ Params: UsernameParams }>('/profiles/:username/follow', async (request) => {
    const followerId = requireUserId(request)
    const target = await loadProfile(request.params.username, followerId)

    if (target.id !== followerId) {
      await prisma.follow.upsert({
        where: { followerId_followedId: { followerId, followedId: target.id } },
        create: { followerId, followedId: target.id },
        update: {},
      })
    }

    return { profile: presentProfile({ ...target, followers: [{ followerId }] }) }
  })

  app.delete<{ Params: UsernameParams }>('/profiles/:username/follow', async (request) => {
    const followerId = requireUserId(request)
    const target = await loadProfile(request.params.username, followerId)

    await prisma.follow.deleteMany({ where: { followerId, followedId: target.id } })

    return { profile: presentProfile({ ...target, followers: [] }) }
  })
}

