import { randomBytes } from 'node:crypto'

/** Lowercase, hyphen-separated ASCII form of a title. */
export function slugify(title: string): string {
  const base = title
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 100)
  return base || 'article'
}

/**
 * Titles are not unique, so every article gets a random suffix. `isTaken` still
 * guards against the (astronomically unlikely) collision.
 */
export async function uniqueSlug(
  title: string,
  isTaken: (slug: string) => Promise<boolean>,
): Promise<string> {
  const base = slugify(title)
  for (let attempt = 0; attempt < 10; attempt += 1) {
    const candidate = `${base}-${randomBytes(4).toString('hex')}`
    if (!(await isTaken(candidate))) return candidate
  }
  throw new Error(`could not generate a unique slug for "${title}"`)
}

