import type { FastifyInstance } from 'fastify'
import { prisma } from '../db.ts'
import { optionalUserId, requireUserId } from '../auth.ts'
import { articleForbidden, articleNotFound } from '../errors.ts'
import { presentArticle } from '../presenters.ts'
import { Validator, requireRoot } from '../validation.ts'
import { articleInclude, articleOrder, findArticleBySlug } from '../articles-shared.ts'
import { uniqueSlug } from '../slug.ts'

const DEFAULT_LIMIT = 20

interface SlugParams {
  slug: string
}

interface ListQuery {
  tag?: string
  author?: string
  favorited?: string
  limit?: string
  offset?: string
}

/** Clamps a query-string integer, falling back to `fallback` when unusable. */
function parseCount(raw: string | undefined, fallback: number, max: number): number {
  const value = Number(raw)
  if (raw === undefined || !Number.isInteger(value) || value < 0) return fallback
  return Math.min(value, max)
}

const slugTaken = async (slug: string) =>
  (await prisma.article.count({ where: { slug } })) > 0

/** Maps tag names onto `Tag` rows, creating any that do not exist yet. */
async function connectTags(tagNames: string[]) {
  const tags = await Promise.all(
    tagNames.map((name) =>
      prisma.tag.upsert({ where: { name }, create: { name }, update: {}, select: { id: true } }),
    ),
  )
  return tags.map((tag) => ({ tagId: tag.id }))
}

export async function registerArticleRoutes(app: FastifyInstance): Promise<void> {
  // Feed must be declared alongside the other routes; Fastify's router already
  // gives this static path precedence over `/articles/:slug`.
  app.get<{ Querystring: ListQuery }>('/articles/feed', async (request) => {
    const viewerId = requireUserId(request)
    const limit = parseCount(request.query.limit, DEFAULT_LIMIT, 100)
    const offset = parseCount(request.query.offset, 0, Number.MAX_SAFE_INTEGER)

    const where = { author: { followers: { some: { followerId: viewerId } } } }
    const [articles, articlesCount] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(viewerId),
        orderBy: [...articleOrder],
        take: limit,
        skip: offset,
      }),
      prisma.article.count({ where }),
    ])

    return { articles: articles.map((article) => presentArticle(article, false)), articlesCount }
  })

  // List articles
  app.get<{ Querystring: ListQuery }>('/articles', async (request) => {
    const viewerId = optionalUserId(request)
    const { tag, author, favorited } = request.query
    const limit = parseCount(request.query.limit, DEFAULT_LIMIT, 100)
    const offset = parseCount(request.query.offset, 0, Number.MAX_SAFE_INTEGER)

    const where = {
      ...(tag ? { tags: { some: { tag: { name: tag } } } } : {}),
      ...(author ? { author: { username: author } } : {}),
      ...(favorited ? { favorites: { some: { user: { username: favorited } } } } : {}),
    }

    const [articles, articlesCount] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(viewerId),
        orderBy: [...articleOrder],
        take: limit,
        skip: offset,
      }),
      prisma.article.count({ where }),
    ])

    return { articles: articles.map((article) => presentArticle(article, false)), articlesCount }
  })

  // Get one article
  app.get<{ Params: SlugParams }>('/articles/:slug', async (request) => {
    const article = await findArticleBySlug(request.params.slug, optionalUserId(request))
    return { article: presentArticle(article) }
  })

  // Create article
  app.post('/articles', async (request, reply) => {
    const authorId = requireUserId(request)
    const payload = requireRoot(request.body, 'article')

    const validator = new Validator()
    const title = validator.requiredString(payload, 'title')
    const description = validator.requiredString(payload, 'description')
    const body = validator.requiredString(payload, 'body')
    const tagList = validator.tagList(payload, 'tagList') ?? []
    validator.throwIfInvalid()

    const now = new Date()
    const article = await prisma.article.create({
      data: {
        slug: await uniqueSlug(title!, slugTaken),
        title: title!,
        description: description!,
        body: body!,
        authorId,
        createdAt: now,
        updatedAt: now,
        tags: { create: await connectTags(tagList) },
      },
      include: articleInclude(authorId),
    })

    return reply.status(201).send({ article: presentArticle(article) })
  })

  // Update article
  app.put<{ Params: SlugParams }>('/articles/:slug', async (request) => {
    const viewerId = requireUserId(request)
    const existing = await prisma.article.findUnique({
      where: { slug: request.params.slug },
      select: { id: true, authorId: true, updatedAt: true },
    })
    if (!existing) throw articleNotFound()
    if (existing.authorId !== viewerId) throw articleForbidden()

    const payload = requireRoot(request.body, 'article')
    const validator = new Validator()
    const title = validator.optionalRequiredString(payload, 'title')
    const description = validator.optionalRequiredString(payload, 'description')
    const body = validator.optionalRequiredString(payload, 'body')
    const tagList = validator.tagList(payload, 'tagList')
    validator.throwIfInvalid()

    // Guarantee a strictly newer timestamp even for back-to-back writes.
    const now = new Date(Math.max(Date.now(), existing.updatedAt.getTime() + 1))

    const article = await prisma.article.update({
      where: { id: existing.id },
      data: {
        ...(title === undefined ? {} : { title }),
        ...(description === undefined ? {} : { description }),
        ...(body === undefined ? {} : { body }),
        ...(tagList === undefined
          ? {}
          : { tags: { deleteMany: {}, create: await connectTags(tagList) } }),
        updatedAt: now,
      },
      include: articleInclude(viewerId),
    })

    return { article: presentArticle(article) }
  })

  // Delete article
  app.delete<{ Params: SlugParams }>('/articles/:slug', async (request, reply) => {
    const viewerId = requireUserId(request)
    const existing = await prisma.article.findUnique({
      where: { slug: request.params.slug },
      select: { id: true, authorId: true },
    })
    if (!existing) throw articleNotFound()
    if (existing.authorId !== viewerId) throw articleForbidden()

    await prisma.article.delete({ where: { id: existing.id } })
    return reply.status(204).send()
  })

  // Favorite / unfavorite
  app.post<{ Params: SlugParams }>('/articles/:slug/favorite', async (request) => {
    const viewerId = requireUserId(request)
    const { id } = await findArticleBySlug(request.params.slug, viewerId)

    await prisma.favorite.upsert({
      where: { userId_articleId: { userId: viewerId, articleId: id } },
      create: { userId: viewerId, articleId: id },
      update: {},
    })

    return { article: presentArticle(await findArticleBySlug(request.params.slug, viewerId)) }
  })

  app.delete<{ Params: SlugParams }>('/articles/:slug/favorite', async (request) => {
    const viewerId = requireUserId(request)
    const { id } = await findArticleBySlug(request.params.slug, viewerId)

    await prisma.favorite.deleteMany({ where: { userId: viewerId, articleId: id } })

    return { article: presentArticle(await findArticleBySlug(request.params.slug, viewerId)) }
  })
}

