import type { FastifyInstance } from 'fastify'
import { prisma } from '../db.ts'
import { optionalUserId, requireUserId } from '../auth.ts'
import { articleNotFound, commentForbidden, commentNotFound } from '../errors.ts'
import { presentComment } from '../presenters.ts'
import { Validator, requireRoot } from '../validation.ts'

interface SlugParams {
  slug: string
}

interface CommentParams extends SlugParams {
  id: string
}

const commentInclude = (viewerId: number | null) =>
  ({
    author: {
      select: {
        username: true,
        bio: true,
        image: true,
        followers: { where: { followerId: viewerId ?? -1 }, select: { followerId: true } },
      },
    },
  }) as const

async function requireArticleId(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } })
  if (!article) throw articleNotFound()
  return article.id
}

export async function registerCommentRoutes(app: FastifyInstance): Promise<void> {
  app.get<{ Params: SlugParams }>('/articles/:slug/comments', async (request) => {
    const viewerId = optionalUserId(request)
    const articleId = await requireArticleId(request.params.slug)

    const comments = await prisma.comment.findMany({
      where: { articleId },
      include: commentInclude(viewerId),
      orderBy: [{ createdAt: 'asc' }, { id: 'asc' }],
    })

    return { comments: comments.map(presentComment) }
  })

  app.post<{ Params: SlugParams }>('/articles/:slug/comments', async (request, reply) => {
    const authorId = requireUserId(request)
    const articleId = await requireArticleId(request.params.slug)

    const payload = requireRoot(request.body, 'comment')
    const validator = new Validator()
    const body = validator.requiredString(payload, 'body')
    validator.throwIfInvalid()

    const comment = await prisma.comment.create({
      data: { body: body!, articleId, authorId },
      include: commentInclude(authorId),
    })

    return reply.status(201).send({ comment: presentComment(comment) })
  })

  app.delete<{ Params: CommentParams }>('/articles/:slug/comments/:id', async (request, reply) => {
    const viewerId = requireUserId(request)
    const articleId = await requireArticleId(request.params.slug)

    const commentId = Number(request.params.id)
    if (!Number.isInteger(commentId)) throw commentNotFound()

    const comment = await prisma.comment.findFirst({
      where: { id: commentId, articleId },
      select: { id: true, authorId: true },
    })
    if (!comment) throw commentNotFound()
    if (comment.authorId !== viewerId) throw commentForbidden()

    await prisma.comment.delete({ where: { id: comment.id } })
    return reply.status(204).send()
  })
}

