import Fastify, { type FastifyInstance } from 'fastify'
import { config } from './config.ts'
import { prisma } from './db.ts'
import { parseAuthorizationHeader, verifyToken } from './auth.ts'
import { ApiError } from './errors.ts'
import { registerUserRoutes } from './routes/users.ts'
import { registerProfileRoutes } from './routes/profiles.ts'
import { registerArticleRoutes } from './routes/articles.ts'
import { registerCommentRoutes } from './routes/comments.ts'
import { registerTagRoutes } from './routes/tags.ts'

declare module 'fastify' {
  interface FastifyRequest {
    /** Set by the authentication hook; `null` when the request is anonymous. */
    currentUserId: number | null
  }
}

export function buildApp(): FastifyInstance {
  const app = Fastify({ logger: { level: config.logLevel } })

  // Bodyless POST/DELETE requests (favorite, follow) arrive without a
  // Content-Type, which Fastify would otherwise reject with 415.
  app.addContentTypeParser('*', (_request, payload, done) => {
    payload.resume()
    payload.on('end', () => done(null, undefined))
  })

  app.decorateRequest('currentUserId', null)

  app.addHook('onRequest', async (request) => {
    const token = parseAuthorizationHeader(request.headers.authorization)
    if (!token) return

    const payload = verifyToken(token)
    const user = await prisma.user.findUnique({
      where: { id: payload.id },
      select: { id: true },
    })
    request.currentUserId = user?.id ?? null
  })

  app.setErrorHandler((error, request, reply) => {
    if (error instanceof ApiError) {
      return reply.status(error.status).send({ errors: error.errors })
    }
    if (error.statusCode === 400 && error.code?.startsWith('FST_ERR_CTP_')) {
      return reply.status(422).send({ errors: { body: ['is invalid'] } })
    }
    if (error.statusCode && error.statusCode < 500) {
      return reply.status(error.statusCode).send({ errors: { body: [error.message] } })
    }

    request.log.error({ err: error }, 'unhandled error')
    return reply.status(500).send({ errors: { body: ['internal server error'] } })
  })

  app.setNotFoundHandler((_request, reply) =>
    reply.status(404).send({ errors: { route: ['not found'] } }),
  )

  app.get('/health', async () => ({ status: 'ok' }))

  app.register(
    async (api) => {
      await registerUserRoutes(api)
      await registerProfileRoutes(api)
      await registerArticleRoutes(api)
      await registerCommentRoutes(api)
      await registerTagRoutes(api)
    },
    { prefix: '/api' },
  )

  return app
}

